# Put the line below in ~/.bashrc or ~/bash_profile:
#
#   eval "$(jump shell bash)"
#
# The following lines are autogenerated:

__jump_prompt_command() {
  local status=$? try=${__jump_boost-}
  unset __jump_boost
  JUMP_TRY=$try jump chdir && return $status
}

__jump_hint() {
  [[ ${#COMP_WORDS[@]} -eq $((COMP_CWORD + 1)) ]] || return

  if [[ ${#COMP_WORDS[@]} -eq 2 ]]; then
    local term="${COMP_WORDS[COMP_CWORD]}"
    mapfile -t COMPREPLY < <(compgen -A directory -- "$term")
    if [[ ${#COMPREPLY[@]} -eq 0 && "$term" != */* ]]; then
      mapfile -t COMPREPLY < <(jump hint "${COMP_WORDS[@]:1}" | head -1)
    fi
  else
    mapfile -t COMPREPLY < <(jump hint "${COMP_WORDS[@]:1}")
  fi
}

__jump_base_dir() {
  local base_dir="$JUMP_BASED_PATH"
  if [ -n "$base_dir" ]; then
    echo "$base_dir"
  elif base_dir="$(command git rev-parse --show-toplevel 2>/dev/null)" && [ -n "$base_dir" ]; then
    echo "$base_dir"
  else
    pwd
  fi
}

{{.Bind}}() {
  case "$1" in
    "..")
      builtin cd ..
      ;;
    "...")
      builtin cd ../..
      ;;
    "-")
      builtin cd -
      ;;
    ".")
      local dir="$(jump cd "$(__jump_base_dir)" ${@:2})"
      [[ $# -gt 1 ]] && __jump_term="${*:2}" __jump_try=0
      builtin cd "$dir"
      ;;
    "")
      __jump_try=$((${__jump_try:-0} + 1))
      local dir="$(JUMP_TERM=${__jump_term-} JUMP_TRY=$__jump_try jump cd)"
      test -d "$dir" && builtin cd "$dir" && __jump_boost=$__jump_try
      ;;
    *)
      local dir="$(jump cd $@)"
      __jump_term="$*" __jump_try=0
      test -d "$dir" && builtin cd "$dir"
      ;;
  esac
}

[[ "$PROMPT_COMMAND" =~ __jump_prompt_command ]] || {
  PROMPT_COMMAND="__jump_prompt_command;$PROMPT_COMMAND"
}

complete -F __jump_hint -o filenames -- {{.Bind}}
